<?php if ($tab === 'agenda'): ?><button class="admin-fab" type="button" data-bs-toggle="modal" data-bs-target="#manualBooking" aria-label="Crear cita manual"><i class="bi bi-plus-lg"></i></button><div class="modal fade" id="manualBooking" tabindex="-1" aria-labelledby="manualBookingTitle" aria-hidden="true"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><form method="post" action="<?= e(app_url('admin/manual')) ?>"><div class="modal-header"><h2 class="modal-title" id="manualBookingTitle">Nueva cita</h2><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Cerrar"></button></div><div class="modal-body"><input type="hidden" name="_token" value="<?= e($csrf) ?>"><label class="form-field">Servicio<select name="service_id" required><?php foreach ($services as $service): if (!$service['activo']) continue; ?><option value="<?= (int) $service['id'] ?>"><?= e($service['nombre']) ?></option><?php endforeach; ?></select></label><div class="form-grid"><label class="form-field">Fecha<input type="date" name="date" min="<?= e(date('Y-m-d')) ?>" value="<?= e($date) ?>" required></label><label class="form-field">Hora<input type="time" name="time" step="900" required></label></div><label class="form-field">Nombre<input name="name" required minlength="2"></label><label class="form-field">WhatsApp<input name="whatsapp" inputmode="tel" required></label><label class="form-field">Nota<textarea name="note" rows="2"></textarea></label></div><div class="modal-footer"><button type="button" class="btn btn-back" data-bs-dismiss="modal">Cerrar</button><button class="btn btn-rose" type="submit">Crear cita</button></div></form></div></div></div><?php endif; ?>
